    keywords: ['subpoena duces tecum', 'documents subpoena', 'records subpoena', 'produce documents', 'bank records subpoena', 'custodian subpoena'],
    fields: [
      { key: 'custodianName', statement: 'This subpoena is directed to the following person or custodian of records: {value}.', label: 'Who must produce the records - the person or organization and, if known, its custodian of records, with a service address?', type: 'textarea', required: true },
      { key: 'recordsRequested', statement: 'The following documents, records, or things must be produced: {value}', label: 'List each category of records precisely - type of record, subject, and date range. Vague all-records demands are the top ground for objections.', type: 'textarea', required: true },
      { key: 'productionPlace', statement: 'Production is to be made at the following place and by the following method: {value}.', label: 'Where and how should the records be produced - delivered to you, to the court, or copies sent electronically?', type: 'select', options: ['Delivered to me', 'Delivered to the court', 'Copies sent electronically'], required: true },
      { key: 'productionDateTime', statement: 'Production is required on or before the following date and time: {value}.', label: 'What is the production date and time? Allow the reasonable time the rules require after service.', required: true },
      { key: 'relevanceBasis', statement: 'The records sought are relevant to this case because: {value}.', label: 'Why are these records relevant to the claims or defenses in the case?', type: 'textarea', required: true },
    ],
    prayer: 'The custodian named above is commanded to produce the records described in this subpoena as stated. Failure to obey may be treated as contempt of court, subject to the right to object or move to quash.',
    companions: ['Notice of the subpoena to all parties (required in most courts before service on a non-party)', 'Proof / Affidavit of Service of the subpoena'],
    bodyHeading: 'Subpoena Details',
    prayerHeading: 'Command',
    proSe: 'Commonly filed without a lawyer - records subpoenas are a routine self-help tool, especially for bank, employment, and medical records the holder will not release voluntarily.',
    gotchas: ['In most courts you must give the other parties notice and a copy of a documents subpoena BEFORE it is served, and non-parties get time to object before production.', 'Medical, bank, and other private records may need a protective order or a signed authorization on top of the subpoena - the subpoena alone does not override every privacy law.'],
